package main

import "fmt"

type entry struct {
	value     string
	expiresAt int
}

type cache map[string]entry

func (c cache) get(key string, now int) (string, bool) {
	item, ok := c[key]
	if !ok || now >= item.expiresAt {
		return "", false
	}
	return item.value, true
}

func main() {
	c := cache{}
	if _, ok := c.get("pokemon/25", 0); !ok {
		fmt.Println("miss")
	}
	c["pokemon/25"] = entry{value: "pikachu", expiresAt: 10}
	if value, ok := c.get("pokemon/25", 5); ok {
		fmt.Println("hit", value)
	}
	if _, ok := c.get("pokemon/25", 10); !ok {
		fmt.Println("expired")
	}
}

